import{_ as n,c as a,a2 as e,o as l}from"./chunks/framework.BnrAgU0Y.js";const h=JSON.parse('{"title":"环境变量","description":"环境变量","frontmatter":{"title":"环境变量","description":"环境变量","layout":"doc"},"headers":[],"relativePath":"langflow/environment-variables.md","filePath":"langflow/environment-variables.md"}'),i={name:"langflow/environment-variables.md"};function p(r,s,t,o,L,c){return l(),a("div",null,s[0]||(s[0]=[e('<h1 id="环境变量" tabindex="-1">环境变量 <a class="header-anchor" href="#环境变量" aria-label="Permalink to &quot;环境变量&quot;">​</a></h1><p>Langflow 允许您使用环境变量来配置多项设置。</p><h2 id="配置环境变量" tabindex="-1">配置环境变量 <a class="header-anchor" href="#配置环境变量" aria-label="Permalink to &quot;配置环境变量&quot;">​</a></h2><p>Langflow 会从以下来源识别<a href="#supported-variables">支持的环境变量</a>：</p><ul><li>你在终端中设置的环境变量。</li><li>你通过 Langflow CLI 使用 <code>--env-file</code> 选项从 <code>.env</code> 文件导入的环境变量。</li></ul><p>你可以选择只使用一个来源，或者同时使用两个来源。如果选择同时使用两个来源，注意从 <code>.env</code> 文件导入的环境变量相比于在终端中设置的具有<a href="#precedence">优先级</a>。</p><h3 id="在终端中设置环境变量" tabindex="-1">在终端中设置环境变量 <a class="header-anchor" href="#在终端中设置环境变量" aria-label="Permalink to &quot;在终端中设置环境变量&quot;">​</a></h3><p>运行以下命令为您当前的终端会话设置环境变量：</p><ul><li><p><strong>Linux 或 macOS</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VARIABLE_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;VALUE&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>Windows</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VARIABLE_NAME=&#39;VALUE&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><strong>Docker</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7860:7860</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VARIABLE_NAME=&#39;VALUE&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    langflowai/langflow:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li></ul><p>当您启动 Langflow 时，它会查找在终端中设置的环境变量。如果检测到受支持的环境变量，它会根据<a href="#precedence">优先级规则</a>自动应用指定的值。</p><h3 id="从-env-文件导入环境变量" tabindex="-1">从 .env 文件导入环境变量 <a class="header-anchor" href="#从-env-文件导入环境变量" aria-label="Permalink to &quot;从 .env 文件导入环境变量&quot;">​</a></h3><ol><li><p>创建一个 <code>.env</code> 文件并用您偏好的编辑器打开。</p></li><li><p>将您的环境变量添加到文件中：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VARIABLE_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;VALUE&#39;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VARIABLE_NAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;VALUE&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><blockquote><p><strong>提示</strong><br> Langflow 项目提供了一个 <a href="https://github.com/langflow-ai/langflow/blob/main/.env.example" target="_blank" rel="noreferrer"><code>.env.example</code></a> 文件，帮助您入门。您可以将此文件的内容复制到您自己的 <code>.env</code> 文件中，并替换示例值为您自己偏好的设置。</p></blockquote></li><li><p>保存并关闭文件。</p></li><li><p>启动 Langflow，使用 <code>--env-file</code> 选项来定义您的 <code>.env</code> 文件路径：</p></li></ol><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 本地</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">```bash</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> langflow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h1 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h1><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7860:7860</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    langflowai/langflow:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>在启动时，Langflow 会从您的 <code>.env</code> 文件中导入环境变量，以及您在<a href="#configure-variables-terminal">终端中设置的任何变量</a>，并采用其指定的值。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>## 优先级</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>环境变量在 `.env` 文件中 [定义](#configure-variables-env-file) 的内容优先于在您的 [终端设置](#configure-variables-terminal) 的内容。 这意味着，如果您在终端和 `.env` 文件中设置了相同的环境变量，Langflow 将采用 `.env` 文件中的值。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>::: tip CLI优先级</span></span>\n<span class="line"><span>[Langflow CLI 选项](/configuration-cli) 会覆盖 `.env` 文件中定义的以及在终端中设置的对应环境变量的值。</span></span>\n<span class="line"><span>:::</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 支持的环境变量</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>下表列出了Langflow支持的环境变量。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```markdown</span></span>\n<span class="line"><span>| 变量 | 格式 / 值 | 默认值 | 描述 |</span></span>\n<span class="line"><span>| --- | --- | --- | --- |</span></span>\n<span class="line"><span>| [`DO_NOT_TRACK`](#DO_NOT_TRACK) | `Boolean` | `false` | 如果启用，Langflow 将不会跟踪遥测数据。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_AUTO_LOGIN`](#LANGFLOW_AUTO_LOGIN) | `Boolean` | `true` | 启用 Langflow 的自动登录。设置为 `false` 将禁用自动登录，并需要登录表单以进入 Langflow UI。设置为 `false` 时需要设置 [`LANGFLOW_SUPERUSER`](#LANGFLOW_SUPERUSER) 和 [`LANGFLOW_SUPERUSER_PASSWORD`](https://your-link/environment-variables#LANGFLOW_SUPERUSER_PASSWORD)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_AUTO_SAVING`](#LANGFLOW_AUTO_SAVING) | `Boolean` | `true` | 启用流的自动保存。参见 [`--auto-saving`](https://your-link/configuration-cli#run-auto-saving) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_AUTO_SAVING_INTERVAL`](#LANGFLOW_AUTO_SAVING_INTERVAL) | `Integer` | `1000` | 设置流自动保存的间隔时间（以毫秒计）。参见 [`--auto-saving-interval`](https://your-link/configuration-cli#run-auto-saving-interval) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_BACKEND_ONLY`](#LANGFLOW_BACKEND_ONLY) | `Boolean` | `false` | 仅运行 Langflow 的后端服务器（不含前端）。参见 [`--backend-only`](https://your-link/configuration-cli#run-backend-only) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_CACHE_TYPE`](#LANGFLOW_CACHE_TYPE) | `async`&lt;br&gt;`redis`&lt;br&gt;`memory`&lt;br&gt;`disk`&lt;br&gt;`critical` | `async` | 设置 Langflow 的缓存类型。如果设置为 `redis`，则必须同时设置以下环境变量：[`LANGFLOW_REDIS_HOST`](#LANGFLOW_REDIS_HOST)、[`LANGFLOW_REDIS_PORT`](#LANGFLOW_REDIS_PORT)、[`LANGFLOW_REDIS_DB`](#LANGFLOW_REDIS_DB) 和 [`LANGFLOW_REDIS_CACHE_EXPIRE`](#LANGFLOW_REDIS_CACHE_EXPIRE)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_COMPONENTS_PATH`](#LANGFLOW_COMPONENTS_PATH) | `String` | `langflow/components` | 自定义组件所在目录的路径。参见 [`--components-path`](https://your-link/configuration-cli#run-components-path) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_CONFIG_DIR`](#LANGFLOW_CONFIG_DIR) | `String` | **Linux/WSL**: `~/.cache/langflow/`&lt;br&gt;**macOS**: `/Users/&lt;username&gt;/Library/Caches/langflow/`&lt;br&gt;**Windows**: `%LOCALAPPDATA%\\langflow\\langflow\\Cache` | 设置存储 Langflow 配置文件、日志和数据库的目录。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DATABASE_URL`](#LANGFLOW_DATABASE_URL) | `String` | 未设置 | 设置 Langflow 的数据库 URL。如果未提供，Langflow 将使用 SQLite 数据库。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DATABASE_CONNECTION_RETRY`](#LANGFLOW_DATABASE_CONNECTION_RETRY) | `Boolean` | `false` | 如果为 `True`，Langflow 将在连接数据库失败后重试连接。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DB_POOL_SIZE`](#LANGFLOW_DB_POOL_SIZE) | `Integer` | `10` | **已弃用：**请改用 `LANGFLOW_DB_CONNECTION_SETTINGS`。保持打开的连接池中的连接数量。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DB_MAX_OVERFLOW`](#LANGFLOW_DB_MAX_OVERFLOW) | `Integer` | `20` | **已弃用：**请改用 `LANGFLOW_DB_CONNECTION_SETTINGS`。允许在连接池大小之外可以打开的连接数量。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DB_CONNECT_TIMEOUT`](#LANGFLOW_DB_CONNECT_TIMEOUT) | `Integer` | `20` | 在放弃等待锁被释放或与数据库建立连接之前等待的秒数。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DB_CONNECTION_SETTINGS`](#LANGFLOW_DB_CONNECTION_SETTINGS) | `JSON` | 未设置 | 用于集中数据库连接参数的 JSON 字典。例如：`{&quot;pool_size&quot;: 10, &quot;max_overflow&quot;: 20}`。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_DEV`](#LANGFLOW_DEV) | `Boolean` | `false` | 在开发模式下运行 Langflow（可能包含错误）。参见 [`--dev`](https://your-link/configuration-cli#run-dev) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_FALLBACK_TO_ENV_VAR`](#LANGFLOW_FALLBACK_TO_ENV_VAR) | `Boolean` | `true` | 如果启用，当 Langflow 无法获取变量值时，在 Langflow UI 中设置的全球变量将回退到具有相同名称的环境变量。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_FRONTEND_PATH`](#LANGFLOW_FRONTEND_PATH) | `String` | `./frontend` | 前端构建文件所在目录的路径。仅用于开发目的。参见 [`--frontend-path`](https://your-link/configuration-cli#run-frontend-path) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_HEALTH_CHECK_MAX_RETRIES`](#LANGFLOW_HEALTH_CHECK_MAX_RETRIES) | `Integer` | `5` | 设置健康检查的最大重试次数。参见 [`--health-check-max-retries`](https://your-link/configuration-cli#run-health-check-max-retries) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_HOST`](#LANGFLOW_HOST) | `String` | `127.0.0.1` | Langflow 服务器将运行的主机。参见 [`--host`](https://your-link/configuration-cli#run-host) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_LANGCHAIN_CACHE`](#LANGFLOW_LANGCHAIN_CACHE) | `InMemoryCache`&lt;br&gt;`SQLiteCache` | `InMemoryCache` | 要使用的缓存类型。参见 [`--cache`](https://your-link/configuration-cli#run-cache) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_LOG_LEVEL`](#LANGFLOW_LOG_LEVEL) | `DEBUG`&lt;br&gt;`INFO`&lt;br&gt;`WARNING`&lt;br&gt;`ERROR`&lt;br&gt;`CRITICAL` | `INFO` | 设置 Langflow 的日志记录级别。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_LOG_FILE`](#LANGFLOW_LOG_FILE) | `String` | 未设置 | 日志文件的路径。如果未设置，日志将写入标准输出。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_MAX_FILE_SIZE_UPLOAD`](#LANGFLOW_MAX_FILE_SIZE_UPLOAD) | `Integer` | `100` | 设置上传文件的最大大小（以兆字节为单位）。参见 [`--max-file-size-upload`](https://your-link/configuration-cli#run-max-file-size-upload) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_MCP_SERVER_ENABLED`](#LANGFLOW_MCP_SERVER_ENABLED) | `Boolean` | `true` | 如果设置为 `False`，Langflow 将不启用 MCP 服务器。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_MCP_SERVER_ENABLE_PROGRESS_NOTIFICATIONS`](#LANGFLOW_MCP_SERVER_ENABLE_PROGRESS_NOTIFICATIONS) | `Boolean` | `false` | 如果设置为 `True`，Langflow 将在 MCP 服务器中发送进度通知。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_NEW_USER_IS_ACTIVE`](#LANGFLOW_NEW_USER_IS_ACTIVE) | `Boolean` | `false` | 启用时，新用户会自动激活，并可以登录而无需超级用户的显式激活。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_OPEN_BROWSER`](#LANGFLOW_OPEN_BROWSER) | `Boolean` | `false` | 在启动时打开系统浏览器。参见 [`--open-browser`](https://your-link/configuration-cli#run-open-browser) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_PORT`](#LANGFLOW_PORT) | `Integer` | `7860` | Langflow 服务器将运行的端口。如果指定的端口被占用，服务器会自动选择一个空闲端口。参见 [`--port`](https://your-link/configuration-cli#run-port) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_PROMETHEUS_ENABLED`](#LANGFLOW_PROMETHEUS_ENABLED) | `Boolean` | `false` | 暴露 Prometheus 指标。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_PROMETHEUS_PORT`](#LANGFLOW_PROMETHEUS_PORT) | `Integer` | `9090` | 设置 Langflow 暴露 Prometheus 指标的端口。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_REDIS_CACHE_EXPIRE`](#LANGFLOW_REDIS_CACHE_EXPIRE) | `Integer` | `3600` | 参见 [`LANGFLOW_CACHE_TYPE`](#LANGFLOW_CACHE_TYPE)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_REDIS_DB`](#LANGFLOW_REDIS_DB) | `Integer` | `0` | 参见 [`LANGFLOW_CACHE_TYPE`](#LANGFLOW_CACHE_TYPE)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_REDIS_HOST`](#LANGFLOW_REDIS_HOST) | `String` | `localhost` | 参见 [`LANGFLOW_CACHE_TYPE`](#LANGFLOW_CACHE_TYPE)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_REDIS_PORT`](#LANGFLOW_REDIS_PORT) | `String` | `6379` | 参见 [`LANGFLOW_CACHE_TYPE`](#LANGFLOW_CACHE_TYPE)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_REMOVE_API_KEYS`](#LANGFLOW_REMOVE_API_KEYS) | `Boolean` | `false` | 从数据库中保存的项目中移除 API 密钥。参见 [`--remove-api-keys`](https://your-link/configuration-cli#run-remove-api-keys) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_SAVE_DB_IN_CONFIG_DIR`](#LANGFLOW_SAVE_DB_IN_CONFIG_DIR) | `Boolean` | `false` | 将 Langflow 数据库保存在 [`LANGFLOW_CONFIG_DIR`](#LANGFLOW_CONFIG_DIR) 中，而不是在 Langflow 包目录中。注意，当此变量设置为默认值（`false`）时，数据库在不同虚拟环境之间不共享，卸载 Langflow 时，数据库会被删除。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_SECRET_KEY`](#LANGFLOW_SECRET_KEY) | `String` | 自动生成 | 用于加密敏感数据（如 API 密钥）的密钥。如果未提供，将自动生成一个安全密钥。在具有多个实例的生产环境中，应显式设置此项以确保实例之间的一致加密。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_STORE`](#LANGFLOW_STORE) | `Boolean` | `true` | 启用 Langflow Store。参见 [`--store`](https://your-link/configuration-cli#run-store) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_STORE_ENVIRONMENT_VARIABLES`](#LANGFLOW_STORE_ENVIRONMENT_VARIABLES) | `Boolean` | `true` | 将环境变量存储为数据库中的 [全局变量](https://your-link/configuration-global-variables)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_SUPERUSER`](#LANGFLOW_SUPERUSER) | `String` | `langflow` | 设置超级用户的名称。如果 [LANGFLOW_AUTO_LOGIN](#LANGFLOW_AUTO_LOGIN) 设置为 `false`，则为必需项。参见 [`superuser --username`](https://your-link/configuration-cli#superuser-username) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_SUPERUSER_PASSWORD`](#LANGFLOW_SUPERUSER_PASSWORD) | `String` | `langflow` | 设置超级用户的密码。如果 [LANGFLOW_AUTO_LOGIN](#LANGFLOW_AUTO_LOGIN) 设置为 `false`，则为必需项。参见 [`superuser --password`](https://your-link/configuration-cli#superuser-password) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT`](#LANGFLOW_VARIABLES_TO_GET_FROM_ENVIRONMENT) | `String` | 未设置 | 逗号分隔的环境变量列表，从环境中获取并存储为 [全局变量](https://your-link/configuration-global-variables)。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_LOAD_FLOWS_PATH`](#LANGFLOW_LOAD_FLOWS_PATH) | `String` | 未设置 | 包含在启动时加载的流 JSON 文件的目录路径。请注意，此功能仅在启用 [`LANGFLOW_AUTO_LOGIN`](#LANGFLOW_AUTO_LOGIN) 时有效。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_WORKER_TIMEOUT`](#LANGFLOW_WORKER_TIMEOUT) | `Integer` | `300` | 工作超时，以秒为单位。参见 [`--worker-timeout`](https://your-link/configuration-cli#run-worker-timeout) 选项。 |</span></span>\n<span class="line"><span>| [`LANGFLOW_WORKERS`](#LANGFLOW_WORKERS) | `Integer` | `1` | 工作进程数量。参见 [`--workers`](https://your-link/configuration-cli#run-workers) 选项。 |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br><span class="line-number">54</span><br><span class="line-number">55</span><br><span class="line-number">56</span><br><span class="line-number">57</span><br><span class="line-number">58</span><br><span class="line-number">59</span><br><span class="line-number">60</span><br><span class="line-number">61</span><br></div></div>',17)]))}const b=n(i,[["render",p]]);export{h as __pageData,b as default};
